const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true});
 const page=await browser.newPage({viewport:{width:1365,height:1000}, deviceScaleFactor:1});
 const errors=[]; page.on('pageerror',e=>errors.push(e.message));
 await page.addInitScript(()=>{const vals=[0,.3,.55,.8];let i=0;Math.random=()=>vals[(i++)%vals.length]});
 await page.goto('http://localhost:3002/',{waitUntil:'networkidle'});
 await page.locator('#start').click();
 await page.locator('.ticket').first().click();
 const checks=page.locator('.proof-row input');
 if(await checks.count()!==3) throw Error(`expected 3 proof checks; got ${await checks.count()}`);
 for(let i=0;i<3;i++) await checks.nth(i).check();
 await page.locator('#verify').click();
 await page.locator('.pad button').first().waitFor();
 const shown={};
 const deadline=Date.now()+5000;
 while(Date.now()<deadline && Object.keys(shown).length<4){
   const cells=await page.locator('#pattern .sig').evaluateAll(nodes=>nodes.map((n,i)=>({i,text:n.textContent,hidden:n.classList.contains('hidden')})));
   for(const c of cells) if(!c.hidden && c.text!=='·') shown[c.i]=c.text;
   await page.waitForTimeout(35);
 }
 const sequence=Object.keys(shown).sort((a,b)=>a-b).map(i=>shown[i]);
 if(sequence.length!==4) throw Error(`failed to observe all 4 symbols: ${JSON.stringify(shown)}`);
 await page.waitForFunction(()=>document.querySelector('#puzzle-hint')?.textContent.includes('Your turn'));
 for(const symbol of sequence) await page.locator(`.pad button[data-symbol="${symbol}"]`).click();
 await page.locator('#next').waitFor({timeout:3000});
 const result=await page.evaluate(()=>({score:document.querySelector('#score').textContent,streak:document.querySelector('#streak').textContent,log:document.querySelector('#log').innerText,queue:document.querySelectorAll('.ticket').length,done:document.querySelector('.done h3')?.textContent}));
 if(result.score!=='1'||result.streak!=='1'||result.queue!==2||!result.log.includes('+100')) throw Error(`completion state incorrect: ${JSON.stringify(result)}`);
 await page.locator('#next').click();
 await page.locator('.empty').waitFor();
 await page.setViewportSize({width:390,height:844});
 await page.screenshot({path:'screenshots/reboot-relay-mobile.jpg',fullPage:true});
 const mobile=await page.evaluate(()=>({width:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,queueVisible:[...document.querySelectorAll('.ticket')].map(e=>getComputedStyle(e).display),bodyHeight:document.body.scrollHeight}));
 console.log(JSON.stringify({sequence,result,mobile,errors},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
