 await page.addInitScript(()=>{const vals=[0,.3,.55,.8];let i=0;Math.random=()=>vals[(i++)%vals.length]});
 await page.goto('http://localhost:3002/',{waitUntil:'networkidle'});
 await page.locator('#start').tap();
 await page.locator('.ticket').first().tap();
 for(const c of await page.locator('.proof-row input').all()) await c.tap();
 await page.locator('#verify').tap();
 const observed={}; const until=Date.now()+5000;
 while(Date.now()<until&&Object.keys(observed).length<4){for(const x of await page.locator('#pattern .sig').evaluateAll(ns=>ns.map((n,i)=>({i,t:n.textContent,h:n.classList.contains('hidden')}))))if(!x.h&&x.t!=='·')observed[x.i]=x.t;await page.waitForTimeout(35)}
 const seq=Object.keys(observed).sort((a,b)=>a-b).map(i=>observed[i]);
 await page.waitForFunction(()=>document.querySelector('#puzzle-hint')?.textContent.includes('Your turn'));
 for(const symbol of seq)await page.locator(`.pad button[data-symbol="${symbol}"]`).tap();
 await page.locator('#next').waitFor(); await page.locator('#next').tap(); await page.locator('.empty').waitFor();
 await page.waitForTimeout(2100);
 const stats=await page.evaluate(()=>({viewport:innerWidth,documentWidth:document.documentElement.scrollWidth,restored:document.querySelector('#score').textContent,requests:document.querySelectorAll('.ticket').length,notes:document.querySelector('#log').innerText}));
 if(stats.viewport!==stats.documentWidth)throw Error(`horizontal overflow ${JSON.stringify(stats)}`);
 await page.screenshot({path:'screenshots/reboot-relay-mobile.jpg',fullPage:true});
 console.log(JSON.stringify({touchFlow:'passed',stats,screenshot:'screenshots/reboot-relay-mobile.jpg'},null,2));
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
